379:             <span class="mode-icon">${icon('broom')}</span>
380:             <small>HIGH-SPEED CIRCUITS</small>
381:             <b>Broom Racing</b>
382:             <span class="mode-meta">${s.stats.races} races · ${s.stats.wins} wins</span>
383:             <span class="mode-cta">Fly now ${icon('chevron')}</span>
384:           </button>
385:           <button class="mode-card quid" data-action="go" data-value="quid">
386:             <div class="mode-glow"></div>
387:             <span class="mode-icon">${icon('quaffle')}</span>
388:             <small>NATIONS · 7 A SIDE</small>
389:             <b>Quidditch</b>
390:             <span class="mode-meta">${qWins} victories · ${s.quidditch.snitch} snitches</span>
391:             <span class="mode-cta">Take the pitch ${icon('chevron')}</span>
