431:   raceScreen() {
432:     const s = this.state;
433:     const sel = this.game.sel;
434:     const track = TRACKS.find(t => t.id === sel.trackId) || TRACKS[0];
435:     const res = s.stats.trackResults?.[track.id];
436:     const best = res?.bestLap ? formatTime(res.bestLap) : 'No best lap yet';
437:     const mode = RACE_MODES.find(m => m.id === sel.mode) || RACE_MODES[0];
438:     const broom = getBroom(s.brooms.selected);
439:     const champ = this.game.championship;
440:     return `<div class="screen race-screen">
441:       <header class="screen-head">
442:         <div><span class="eyebrow-small">INTERNATIONAL CIRCUIT</span><h2>Broom Racing</h2><p>Seven circuits. One crown.</p></div>
443:         <div class="head-badge">${icon('broom')}<b>${s.stats.wins}</b><small>wins</small></div>
444:       </header>
445: 
446:       <div class="seg-chips scroll-x">
447:         ${RACE_MODES.map(m => `<button class="chip ${sel.mode === m.id ? 'active' : ''}" data-action="select-mode" data-value="${m.id}">${icon(m.icon)}${m.name}</button>`).join('')}
448:       </div>
449:       <p class="mode-desc">${mode.desc}</p>
450: 
451:       ${sel.mode === 'championship' ? `<div class="champ-banner">
452:         <div><small>${CHAMPIONSHIP.name}</small><b>${champ ? `Round ${Math.min(3, champ.round + 1)} of 3` : 'Three circuits · points decide everything'}</b></div>
453:         <div class="champ-tracks">${CHAMPIONSHIP.tracks.map((id, i) => `<span class="${champ && champ.round > i ? 'done' : ''}">${i + 1}</span>`).join('')}</div>
454:       </div>` : ''}
455: 
456:       <div class="section-title"><span>Select circuit</span><small>Tap a circuit to inspect</small></div>
457:       <div class="track-scroller scroll-x" id="track-scroller">
458:         ${TRACKS.map(t => trackCard(t, t.id === sel.trackId, s)).join('')}
459:       </div>
460: 
461:       <div class="track-detail">
462:         <div class="detail-head">
463:           <div><small>${track.region}</small><h3>${track.name}</h3></div>
464:           <span class="difficulty">${pips(track.difficulty)} <small>${['', 'Academy', 'Professional', 'World Class'][track.difficulty]}</small></span>
465:         </div>
466:         <p>${track.desc}</p>
467:         <div class="detail-grid">
468:           <div>${icon('flag')}<span>Weather</span><b>${weatherLabel(track.weather)}</b></div>
469:           <div>${icon('compass')}<span>Laps</span><b>${sel.mode === 'trial' || sel.mode === 'qualify' ? 1 : track.laps}</b></div>
470:           <div>${icon('clock')}<span>Best lap</span><b>${best}</b></div>
471:           <div>${icon('wind')}<span>Wind</span><b>${Math.round(track.wind * 100)}%</b></div>
472:         </div>
473:       </div>
474: 
475:       <div class="section-title"><span>Opponents</span><small>${sel.mode === 'trial' ? 'The clock is your only rival' : 'Five rival flyers'}</small></div>
476:       <div class="seg-chips">
477:         ${DIFFICULTIES.map(d => `<button class="chip ${sel.difficulty === d.id ? 'active' : ''}" data-action="select-difficulty" data-value="${d.id}">${d.name}</button>`).join('')}
478:       </div>
479:       <p class="mode-desc">${DIFFICULTIES.find(d => d.id === sel.difficulty)?.desc || ''}</p>
480: 
481:       <div class="broom-select" data-action="go" data-value="locker">
482:         <div class="broom-thumb">${broomArt(broom, LIVERIES.find(l => l.id === s.brooms.livery)?.color)}</div>
483:         <div class="broom-select-body">
484:           <small>YOUR BROOM · TIER ${broom.tier}</small>
485:           <b>${broom.name}</b>
486:           <div class="micro-stats">
487:             <span>SPD ${Math.round(getBroomStats(s, broom.id).speed)}</span>
488:             <span>HND ${Math.round(getBroomStats(s, broom.id).handling)}</span>
489:             <span>BST ${Math.round(getBroomStats(s, broom.id).boost)}</span>
490:           </div>
491:         </div>
492:         ${icon('chevron')}
493:       </div>
494: 
495:       <div class="launch-bar">
496:         <div><small>${mode.name} · ${track.name}</small><b>${sel.mode === 'championship' ? 'Grand Prix' : track.region}</b></div>
497:         <button class="btn gold" data-action="open-briefing">${icon('play')} ${sel.mode === 'championship' ? 'Enter Grand Prix' : 'Race'}</button>
498:       </div>
499:       <div class="screen-pad"></div>
500:     </div>`;
