531:           ${crest(n)}
532:           <b>${n.name}</b><small>${n.city}</small>
533:         </button>`).join('')}
534:       </div>
535:       <div class="nation-strip">
536:         <div>${icon('castle')}<span><small>Home stadium</small><b>${nation.stadium}</b></span></div>
537:         <div>${icon('shield')}<span><small>National symbol</small><b>${nation.beast}</b></span></div>
538:       </div>` : ''}
539: 
540:       <div class="section-title"><span>Your position</span><small>Switch roles at any substitution</small></div>
541:       <div class="role-grid">
542:         ${POSITIONS.map(p => `<button class="role-card ${sel.role === p.id ? 'active' : ''}" data-action="select-role" data-value="${p.id}" style="--role:${p.color}">
543:           <span class="role-icon">${icon(p.icon)}</span><b>${p.name}</b><small>${p.desc}</small>
544:         </button>`).join('')}
545:       </div>
546: 
547:       <div class="section-title"><span>Tactics</span><small>How will your team play?</small></div>
548:       <div class="seg-chips">
549:         ${TACTICS.map(x => `<button class="chip ${sel.tactics === x.id ? 'active' : ''}" data-action="select-tactics" data-value="${x.id}">${x.name}</button>`).join('')}
550:       </div>
551:       <p class="mode-desc">${TACTICS.find(x => x.id === sel.tactics)?.desc || ''}</p>
552:       <div class="seg-chips">
553:         ${DIFFICULTIES.map(d => `<button class="chip ${sel.qDifficulty === d.id ? 'active' : ''}" data-action="select-qdifficulty" data-value="${d.id}">${d.name}</button>`).join('')}
554:       </div>
555: 
556:       <div class="launch-bar">
557:         <div><small>${t && !t.champion && !t.eliminated ? (fixture?.roundName || 'World Cup') : 'Quidditch World Cup'}</small><b>${opp ? `vs ${opp.name}` : `${nation.name} · ${role.name}`}</b></div>
558:         ${t && !t.champion && !t.eliminated
559:           ? `<button class="btn gold" data-action="start-match">${icon('play')} Play Match</button>`
560:           : `<button class="btn gold" data-action="start-campaign">${icon('trophy')} ${t?.champion ? 'New Campaign' : 'Enter World Cup'}</button>`}
561:       </div>
562:       <div class="screen-pad"></div>
563:     </div>`;
