565: 
566:   tournamentPanel(t, fixture) {
567:     const rounds = t.rounds;
568:     const nationOf = id => NATIONS.find(n => n.id === id) || NATIONS[0];
569:     return `<div class="bracket-card">
570:       <div class="bracket-head">
571:         <div><small>KNOCKOUT STAGE</small><b>${nationOf(t.nation).name} · ${DIFFICULTIES.find(d => d.id === t.difficulty)?.name || 'Professional'}</b></div>
572:         <span class="bracket-status ${t.champion ? 'champion' : t.eliminated ? 'out' : ''}">${t.champion ? 'CHAMPIONS' : t.eliminated ? 'ELIMINATED' : (fixture?.roundName || '')}</span>
573:       </div>
574:       <div class="bracket">
575:         ${rounds.map((r, ri) => `<div class="bracket-round ${ri === t.round && !t.champion ? 'current' : ''}">
576:           <h5>${r.name}</h5>
577:           ${r.matches.map(m => {
578:             const a = nationOf(m.a), b = nationOf(m.b);
579:             const involved = m.a === t.nation || m.b === t.nation;
580:             const played = m.played;
581:             const scoreA = played && m.sa !== undefined ? m.sa : '—';
582:             const scoreB = played && m.sb !== undefined ? m.sb : '—';
583:             return `<div class="bracket-match ${involved ? 'involved' : ''}">
