1151:     ctx.strokeStyle = 'rgba(255,221,150,0.28)';
1152:     ctx.lineWidth = 3;
1153:     ctx.beginPath();
1154:     pts.forEach((p, i) => { const [x, y] = map(p[0], p[2]); if (i === 0) ctx.moveTo(x, y); else ctx.lineTo(x, y); });
1155:     ctx.closePath(); ctx.stroke();
1156:     // gates
1157:     (this.game.active?.world.gates || []).forEach((g, i) => {
1158:       const [x, y] = map(g.pos.x, g.pos.z);
1159:       const active = i === (data.nextGate % pts.length);
1160:       ctx.beginPath();
1161:       ctx.arc(x, y, active ? 4.2 : 2.3, 0, Math.PI * 2);
1162:       ctx.fillStyle = g.mod === 'warp' ? '#bb8bff' : active ? '#ffe08a' : 'rgba(180,220,240,0.55)';
