493: 
494:   raceConfig(trackId = this.sel.trackId) {
495:     let track = TRACKS.find(t => t.id === trackId) || TRACKS[0];
496:     if (this.sel.mode === 'championship') {
497:       if (!this.championship || this.championship.finished) {
498:         this.championship = { round: 0, points: {}, finished: false, tracks: CHAMPIONSHIP.tracks };
499:       }
500:       const id = CHAMPIONSHIP.tracks[Math.min(2, this.championship.round)];
501:       track = TRACKS.find(t => t.id === id) || TRACKS[0];
502:       this.sel.trackId = track.id;
503:     }
504:     return {
505:       track,
506:       broomId: this.state.brooms.selected,
507:       mode: this.sel.mode,
508:       difficulty: this.sel.difficulty,
509:       laps: this.sel.mode === 'trial' || this.sel.mode === 'qualify' ? 1 : track.laps,
510:     };
511:   }
