558:       this.preview = null;
559:     }
560:     this.ui.els.fade.classList.add('show');
561:     setTimeout(() => {
562:       try {
563:         this.startRace(this.previewCfg || this.raceConfig());
564:       } catch (err) {
565:         console.error(err);
566:         this.ui.toast('Unable to start race', String(err.message || err), 'close');
567:         this.mode = 'menu';
568:         this.ui.renderChrome();
569:       }
570:       setTimeout(() => this.ui.els.fade.classList.remove('show'), 200);
571:     }, 180);
572:   }
