574:   startRace(config) {
575:     this.leaveGame();
576:     const cfg = config || this.raceConfig();
577:     this.lastRaceConfig = cfg;
578:     if (cfg.mode === 'championship') {
579:       if (!this.championship || this.championship.finished) {
580:         this.championship = { round: 0, points: {}, finished: false, tracks: CHAMPIONSHIP.tracks };
581:       }
582:       cfg.championship = { round: this.championship.round };
583:     }
584:     this.mode = 'race';
585:     this.paused = false;
586:     this.active = new RaceGame(this, cfg);
587:     this.ui.renderChrome();
588:     this.audio.init();
589:   }
