592:     const cfg = this.lastRaceConfig ? { ...this.lastRaceConfig } : this.raceConfig();
593:     if (cfg.mode === 'championship') cfg.mode = 'quick';
594:     this.ui.closeModal();
595:     this.startRace(cfg);
