690:   startCampaign() {
691:     const t = this.state.quidditch.tournament;
692:     if (t && !t.champion && !t.eliminated) {
693:       this.ui.go('quid');
694:       return;
695:     }
696:     const nation = NATIONS.find(n => n.id === this.state.profile.nation) || NATIONS[0];
697:     resetTournament(this.state);
698:     startTournament(this.state, nation.id, this.sel.qDifficulty);
699:     this.save();
700:     this.audio.sfx('whistle');
701:     this.ui.rerender();
702:     this.ui.toast('World Cup draw complete', `${nation.name} enter the quarter-final`, 'quaffle');
703:   }
