705:   startMatch(config) {
706:     this.ui.closeModal();
707:     this.leaveGame();
708:     const t = this.state.quidditch.tournament;
709:     const fixture = currentFixture(this.state);
710:     if (!t || !fixture) {
711:       this.ui.toast('No fixture available', 'Enter the World Cup to begin a campaign', 'quaffle');
712:       this.ui.go('quid');
713:       return;
714:     }
715:     const cfg = config || {
716:       nationId: t.nation,
717:       opponentId: fixture.opponentId,
718:       round: fixture.round,
719:       roundName: fixture.roundName,
720:       difficulty: t.difficulty,
721:       role: this.sel.role,
722:       tactics: this.sel.tactics,
723:     };
724:     this.lastMatchConfig = cfg;
725:     this.mode = 'quidditch';
726:     this.paused = false;
727:     try {
728:       this.active = new QuidditchMatch(this, cfg);
729:       this.ui.renderChrome();
730:       this.audio.init();
731:     } catch (err) {
732:       console.error(err);
733:       this.ui.toast('Unable to start match', String(err.message || err), 'close');
734:       this.mode = 'menu';
735:       this.ui.go('quid');
736:     }
737:   }
738: 
739:   completeQuidditch(summary) {
740:     const t = this.state.quidditch.tournament;
741:     const round = summary.round;
742:     const result = completeTournamentMatch(this.state, summary.scoreFor, summary.scoreAgainst);
743:     const reward = tournamentMatchRewards(round, summary.won);
744:     if (result.champion) {
745:       reward.galleons += 1000;
746:       reward.xp += 400;
747:       reward.ranking += 100;
748:     }
749:     recordQuidditch(this.state, {
750:       won: summary.won,
751:       goals: summary.goals,
752:       saves: summary.saves,
753:       bludgers: summary.bludgers,
754:       snitch: summary.snitch,
755:       opponentId: summary.opponentId,
756:       opponentName: summary.opponentName,
757:       nationName: summary.nationName,
758:       roundName: summary.roundName,
759:       scoreFor: summary.scoreFor,
760:       scoreAgainst: summary.scoreAgainst,
761:     });
762:     const levels = award(this.state, reward);
763:     const achievements = checkAchievements(this.state);
764:     this.save();
765:     this.ui.renderChrome();
766:     const next = currentFixture(this.state);
767:     this.ui.showQuidditchResults(summary, reward, {
768:       levels: levels.levels,
769:       achievements,
770:       tournament: this.state.quidditch.tournament,
771:       nextFixture: next,
772:       champion: result.champion,
773:       eliminated: result.eliminated,
774:     });
775:     this.audio.setMode('menu');
776:     if (summary.won) this.audio.sfx('win');
777:     else this.audio.sfx('lose');
778:   }
