810:   quitGame() { this.leaveGame(); this.ui.go('home'); }
811: 
812:   restartCurrent() {
813:     const isQuid = this.mode === 'quidditch';
814:     const raceCfg = this.lastRaceConfig ? { ...this.lastRaceConfig } : null;
815:     const matchCfg = this.lastMatchConfig ? { ...this.lastMatchConfig } : null;
816:     this.ui.closeModal();
817:     this.leaveGame();
818:     if (isQuid && matchCfg) this.startMatch(matchCfg);
819:     else if (raceCfg) this.startRace(raceCfg);
820:     else this.go('home');
