}
.mode-card:active { transform: scale(0.975); }
.mode-card.race { background: linear-gradient(155deg, #2c3f2c 0%, #16241f 44%, #0b1218 100%); }
.mode-card.quid { background: linear-gradient(155deg, #372846 0%, #201a36 45%, #0d0e1a 100%); }
.mode-card::after { content: ''; position: absolute; inset: 0; border-radius: inherit; box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.09), inset 0 -26px 40px rgba(0, 0, 0, 0.35); pointer-events: none; }
.mode-glow { position: absolute; width: 120px; height: 120px; top: -42px; right: -38px; border-radius: 50%; filter: blur(6px); opacity: 0.5; }
.mode-card.race .mode-glow { background: radial-gradient(circle, rgba(237, 196, 106, 0.55), transparent 68%); }
.mode-card.quid .mode-glow { background: radial-gradient(circle, rgba(161, 131, 255, 0.5), transparent 68%); }
.mode-icon {
  width: 39px; height: 39px; border-radius: 12px; display: grid; place-items: center; margin-bottom: 16px;
  background: rgba(255, 255, 255, 0.08); border: 1px solid rgba(255, 255, 255, 0.12); color: var(--gold-hot);
}
