/* -------- Modal shell --------------------------------------------- */

#modal-root { position: fixed; inset: 0; z-index: 120; pointer-events: none; }
#modal-root:has(.modal-backdrop) { pointer-events: auto; }
.modal-backdrop {
  position: fixed; inset: 0; z-index: 120; display: flex; align-items: center; justify-content: center;
  padding: calc(10px + var(--safe-t)) 10px calc(10px + var(--safe-b));
  background: rgba(2, 4, 9, 0.68); backdrop-filter: blur(8px) saturate(0.9);
  opacity: 0; transition: opacity 0.24s var(--ease);
}
.modal-backdrop.in { opacity: 1; }
.modal-card {
  width: 100%; max-width: 480px; max-height: calc(100dvh - 20px - var(--safe-t) - var(--safe-b));
  overflow-y: auto; scrollbar-width: none; -webkit-overflow-scrolling: touch;
  position: relative; border-radius: 26px; border: 1px solid rgba(236, 218, 174, 0.18);
  background: linear-gradient(180deg, #101728 0%, #090d17 55%, #060910 100%);
  box-shadow: 0 26px 90px rgba(0, 0, 0, 0.7), inset 0 1px 0 rgba(255, 255, 255, 0.08);
  transform: translateY(16px) scale(0.985); transition: transform 0.32s var(--ease);
}
.modal-card::-webkit-scrollbar { display: none; }
.modal-backdrop.in .modal-card { transform: none; }
.modal-head { display: flex; align-items: flex-start; justify-content: space-between; gap: 10px; padding: 18px 18px 10px; }
.modal-head small { display: block; font-size: 7.5px; letter-spacing: 0.16em; color: var(--gold); font-weight: 700; margin-bottom: 2px; }
.modal-head h3 { font-family: var(--serif); font-size: 26px; font-weight: 500; letter-spacing: -0.02em; }

/* -------- Onboarding ---------------------------------------------- */

.onboard-card { border-color: rgba(233, 196, 106, 0.26); }
.onboarding { padding: 24px 20px 18px; }
.onboard-crest { width: 54px; height: 54px; display: grid; place-items: center; border-radius: 17px; margin-bottom: 14px; color: var(--gold-hot); border: 1px solid rgba(233, 196, 106, 0.3); background: linear-gradient(150deg, rgba(233, 196, 106, 0.2), rgba(233, 196, 106, 0.03)); box-shadow: 0 8px 26px rgba(233, 196, 106, 0.1); }
.onboard-crest .icon { width: 27px; height: 27px; }
.onboarding h2 { font-family: var(--serif); font-size: 35px; font-weight: 500; line-height: 1; letter-spacing: -0.03em; margin-bottom: 7px; }
.onboard-sub { font-size: 10.5px; line-height: 1.55; color: var(--muted); margin-bottom: 18px; }
.big-input { display: flex; flex-direction: column; gap: 5px; margin-bottom: 14px; }
.big-input span { font-size: 8px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--gold); }
.big-input input, .big-input select { height: 44px; border-radius: 12px; font-size: 14px; }
.onboard-section { margin-bottom: 14px; }
.onboard-section > span { display: block; font-size: 8px; letter-spacing: 0.12em; text-transform: uppercase; color: var(--gold); margin-bottom: 6px; }
.house-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; }
.house-option { display: grid; grid-template-columns: 22px 1fr; grid-template-rows: auto auto; align-items: center; gap: 0 6px; padding: 8px; border-radius: 11px; border: 1px solid rgba(255, 255, 255, 0.08); background: rgba(255, 255, 255, 0.026); text-align: left; }
.house-option i { grid-row: span 2; width: 21px; height: 25px; border-radius: 3px 3px 7px 7px; background: linear-gradient(160deg, var(--c), color-mix(in srgb, var(--c) 55%, #05070d)); border: 1px solid color-mix(in srgb, var(--a) 60%, transparent); }
.house-option b { font-size: 9.5px; font-weight: 600; }
