.speed-value b { font-family: var(--serif); font-size: 30px; font-weight: 500; line-height: 0.9; color: var(--cream); font-variant-numeric: tabular-nums; }
.speed-value small { font-size: 7px; letter-spacing: 0.1em; color: var(--gold); }
.boost-meter { position: relative; height: 17px; border-radius: 999px; background: rgba(7, 11, 20, 0.6); border: 1px solid rgba(255, 255, 255, 0.14); overflow: hidden; }
.boost-fill { height: 100%; width: 100%; border-radius: 999px; background: linear-gradient(90deg, #9b742c, #e9c46a 55%, #fff0bf); transition: width 0.1s linear; box-shadow: 0 0 12px rgba(255, 214, 120, 0.4); }
.boost-fill.full { animation: boost-pulse 0.7s infinite; }
@keyframes boost-pulse { 50% { filter: brightness(1.4); } }
.boost-meter span { position: absolute; inset: 0; display: grid; place-items: center; font-size: 5.5px; font-weight: 800; letter-spacing: 0.16em; color: rgba(20, 12, 3, 0.7); text-shadow: 0 1px 0 rgba(255, 255, 255, 0.25); }
.race-objective { position: absolute; z-index: 3; left: 14px; bottom: calc(268px + var(--safe-b)); display: flex; align-items: center; gap: 4px; padding: 4px 8px; border-radius: 999px; background: rgba(7, 11, 20, 0.55); border: 1px solid rgba(255, 255, 255, 0.1); font-size: 8px; color: var(--muted); max-width: 200px; }
.race-objective .icon { width: 10px; height: 10px; color: var(--gold); }

.controls { position: absolute; inset: 0; z-index: 5; pointer-events: none; }
.joystick-wrap { position: absolute; left: 18px; bottom: calc(22px + var(--safe-b)); display: flex; flex-direction: column; align-items: center; gap: 3px; pointer-events: none; }
.joystick {
  width: 116px; height: 116px; border-radius: 50%; position: relative; touch-action: none; pointer-events: auto;
  background: radial-gradient(circle at 50% 44%, rgba(255, 255, 255, 0.06), rgba(7, 11, 20, 0.5) 62%, rgba(7, 11, 20, 0.7));
  border: 1px solid rgba(255, 255, 255, 0.15);
  box-shadow: inset 0 0 26px rgba(0, 0, 0, 0.4), 0 6px 20px rgba(0, 0, 0, 0.3);
