}
.joystick::before { content: ''; position: absolute; inset: 17px; border-radius: 50%; border: 1px dashed rgba(233, 196, 106, 0.18); }
.joy-glow { position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; transform: translate(-50%, -50%); border-radius: 50%; background: radial-gradient(circle, rgba(233, 196, 106, 0.22), transparent 68%); filter: blur(3px); }
.joy-knob {
  position: absolute; left: 50%; top: 50%; width: 48px; height: 48px; margin: -24px 0 0 -24px; border-radius: 50%;
  display: grid; place-items: center; color: rgba(255, 240, 200, 0.85);
  background: radial-gradient(circle at 38% 30%, rgba(255, 242, 204, 0.26), rgba(133, 108, 58, 0.4) 48%, rgba(26, 27, 31, 0.7));
  border: 1px solid rgba(255, 228, 160, 0.45); box-shadow: 0 4px 14px rgba(0, 0, 0, 0.45), inset 0 1px 0 rgba(255, 255, 255, 0.28);
