.round-btn.brake .icon { width: 18px; height: 18px; }
.round-btn.brake span { font-size: 5.5px; }
.round-btn.pressed, .round-btn:active { transform: scale(0.93); filter: brightness(1.15); }
.round-btn:disabled { opacity: 0.55; }
.round-btn.action { width: 82px; height: 82px; color: #2a1c05; border-color: rgba(255, 235, 180, 0.65); background: radial-gradient(circle at 38% 28%, #fff0c2, #e5bd64 55%, #a87a28); box-shadow: 0 6px 22px rgba(233, 196, 106, 0.28), inset 0 1px 0 rgba(255, 255, 255, 0.6); }
