319:     const target = (this.boostHeld ? baseSpeed * 1.6 : baseSpeed) * (stunned ? 0.3 : 1);
320:     p.speed = lerp(p.speed, target, 1 - Math.exp(-dt * 3.2));
321:     const turn = 1.45 + (this.state.skills.handling || 0) * 0.02;
