329:       const desiredYaw = Math.atan2(-targetDir.x, -targetDir.z);
330:       const d = angleDiff(desiredYaw, p.yaw);
331:       if (Math.abs(d) < 1.2) p.yaw += d * dt * 0.5;
332:     }
333:     p.bank = lerp(p.bank, -moveX * 0.5, 1 - Math.exp(-dt * 5));
334:     const q = new THREE.Quaternion().setFromEuler(new THREE.Euler(p.pitch, p.yaw, 0, 'YXZ'));
335:     const forward = new THREE.Vector3(0, 0, -1).applyQuaternion(q);
