if (!page) throw new Error('No browser page');
const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, {once:true}); ws.addEventListener('error', reject, {once:true}); });
let id = 0; const pending = new Map();
ws.addEventListener('message', e => { const m=JSON.parse(e.data); if(m.id && pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result);} });
const cdp=(method,params={})=>new Promise((resolve,reject)=>{const n=++id;pending.set(n,{resolve,reject});ws.send(JSON.stringify({id:n,method,params}));});
const ev=async expression=>(await cdp('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result?.value;
await cdp('Emulation.setDeviceMetricsOverride',{width:390,height:844,deviceScaleFactor:1,mobile:true,screenWidth:390,screenHeight:844});
await new Promise(r=>setTimeout(r,2000));
console.log('title',await ev('document.title'),'screen',await ev('document.querySelector("#screen")?.innerText.slice(0,100)'));
await ev(`document.querySelector('[data-action="go"][data-value="quid"]')?.click()`);
await new Promise(r=>setTimeout(r,300));
await ev(`document.querySelector('[data-action="start-campaign"]')?.click()`);
await new Promise(r=>setTimeout(r,400));
