const ws = new WebSocket(page.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.addEventListener('open', resolve, {once:true}); ws.addEventListener('error', reject, {once:true}); });
let id = 0; const pending = new Map();
ws.addEventListener('message', e => { const m=JSON.parse(e.data); if(m.id && pending.has(m.id)){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result);} });
const cdp=(method,params={})=>new Promise((resolve,reject)=>{const n=++id;pending.set(n,{resolve,reject});ws.send(JSON.stringify({id:n,method,params}));});
const ev=async expression=>(await cdp('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true})).result?.value;
await ev(`new Promise(r=>setTimeout(r,14000))`);
console.log('state', await ev(`({countdown:document.getElementById('quid-countdown')?.textContent, objective:document.getElementById('quid-objective')?.innerText, map:document.querySelector('.quid-minimap-wrap')?.getBoundingClientRect().toJSON(), commentary:document.getElementById('quid-commentary')?.getBoundingClientRect().toJSON(), joystick:document.getElementById('joystick-zone')?.getBoundingClientRect().toJSON(), label:document.querySelector('.control-label')?.getBoundingClientRect().toJSON()})`));
await ev(`(()=>{const z=document.getElementById('joystick-zone').getBoundingClientRect();const x=z.left+z.width/2,y=z.top+z.height/2;const ev=(type,px,py)=>window.dispatchEvent(new PointerEvent(type,{pointerId:17,pointerType:'touch',clientX:px,clientY:py,bubbles:true}));const target=document.elementFromPoint(x,y);target.dispatchEvent(new PointerEvent('pointerdown',{pointerId:17,pointerType:'touch',clientX:x,clientY:y,bubbles:true}));ev('pointermove',x+35,y-30);setTimeout(()=>window.dispatchEvent(new PointerEvent('pointerup',{pointerId:17,pointerType:'touch',clientX:x+35,clientY:y-30,bubbles:true})),2800);const a=document.getElementById('btn-action').getBoundingClientRect();setTimeout(()=>{const b=document.elementFromPoint(a.x+a.width/2,a.y+a.height/2);b?.dispatchEvent(new PointerEvent('pointerdown',{pointerId:18,pointerType:'touch',clientX:a.x+a.width/2,clientY:a.y+a.height/2,bubbles:true}));setTimeout(()=>window.dispatchEvent(new PointerEvent('pointerup',{pointerId:18,pointerType:'touch',clientX:a.x+a.width/2,clientY:a.y+a.height/2,bubbles:true})),150)},500);return true})()`);
await ev(`new Promise(r=>setTimeout(r,5000))`);
console.log('hud', await ev(`({countdown:document.getElementById('quid-countdown')?.textContent, objective:document.getElementById('quid-objective')?.innerText, clock:document.getElementById('quid-clock')?.textContent, comment:document.getElementById('quid-commentary')?.innerText, warning:document.getElementById('quid-warning')?.innerText})`));
const snap=await cdp('Page.captureScreenshot',{format:'png',captureBeyondViewport:false});
await fs.writeFile('/tmp/opencode/mobile-gameplay-active.png',Buffer.from(snap.data,'base64'));
console.log('shot /tmp/opencode/mobile-gameplay-active.png');
ws.close();
