1353: function createConfetti(scene) {
1354:   const count = 450;
1355:   const geo = new THREE.BufferGeometry();
1356:   const pos = new Float32Array(count * 3);
1357:   const colors = new Float32Array(count * 3);
1358:   const c = new THREE.Color();
1359:   for (let i = 0; i < count; i++) {
1360:     pos[i * 3] = (Math.random() - 0.5) * 180;
1361:     pos[i * 3 + 1] = 20 + Math.random() * 60;
1362:     pos[i * 3 + 2] = (Math.random() - 0.5) * 120;
1363:     c.setHSL(Math.random(), 0.8, 0.6);
1364:     colors[i * 3] = c.r; colors[i * 3 + 1] = c.g; colors[i * 3 + 2] = c.b;
1365:   }
1366:   geo.setAttribute('position', new THREE.BufferAttribute(pos, 3));
1367:   geo.setAttribute('color', new THREE.BufferAttribute(colors, 3));
1368:   const mat = new THREE.PointsMaterial({ size: 1.1, vertexColors: true, transparent: true, opacity: 0, depthWrite: false });
1369:   const points = new THREE.Points(geo, mat);
1370:   scene.add(points);
1371:   let intensity = 0;
1372:   return {
1373:     points,
1374:     burst() {
1375:       intensity = 1; mat.opacity = 0.95;
1376:       const p = geo.attributes.position.array;
1377:       for (let i = 0; i < count; i++) { p[i * 3 + 1] = 20 + Math.random() * 50; }
1378:       geo.attributes.position.needsUpdate = true;
1379:     },
1380:     update(dt) {
