const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const target = targets.find(t => t.type === 'page' && t.url.startsWith('http://127.0.0.1:3002/'));
if (!target) throw new Error('Game page not found');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
ws.onmessage = event => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) {
    const { resolve } = pending.get(msg.id); pending.delete(msg.id); resolve(msg);
  } else if (msg.method === 'Runtime.consoleAPICalled') {
    const args = msg.params.args || [];
    if (args.some(arg => String(arg.value || arg.description || '').includes('Unknown color'))) {
      console.log('CONSOLE', JSON.stringify(args.map(a => a.value || a.description)));
    }
  }
};
function send(method, params = {}) {
  const requestId = ++id;
  ws.send(JSON.stringify({ id: requestId, method, params }));
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => { pending.delete(requestId); reject(new Error(`${method} timeout`)); }, 10000);
    pending.set(requestId, { resolve: msg => { clearTimeout(timer); resolve(msg); } });
  });
}
await send('Runtime.enable');
const result = await send('Runtime.evaluate', { expression: `({title:document.title, url:location.href, dpr:devicePixelRatio, viewport:[innerWidth,innerHeight], body:document.body.className, hud:document.querySelector('#quid-hud')?.getBoundingClientRect().toJSON(), elements:[...document.querySelectorAll('.scoreboard,.quid-commentary,.quid-objective,.quid-minimap-wrap,.role-chip,.joystick-wrap,.quid-actions,.quid-boost')].map(e=>({class:e.className,rect:e.getBoundingClientRect().toJSON(),text:e.innerText}))})`, returnByValue: true });
console.log(JSON.stringify(result.result?.result?.value, null, 2));
ws.close();

