548: export function createStadium(scene, opts = {}) {
549:   const {
550:     colors = ['#9e1b32', '#f3e7ce'], accent = '#e2b954', scale = 1,
551:     hoops = true, crowd = 1200, seed = 5, logo = 'WC',
552:   } = opts;
553:   const group = new THREE.Group();
554:   group.scale.setScalar(scale);
555: 
556:   // Pitch
557:   const pitchGeo = new THREE.CircleGeometry(1, 64);
558:   pitchGeo.rotateX(-Math.PI / 2);
559:   const pitch = new THREE.Mesh(pitchGeo, new THREE.MeshStandardMaterial({
560:     color: '#3d6b3a', roughness: 1,
561:   }));
562:   pitch.scale.set(90, 1, 55);
563:   pitch.receiveShadow = true;
564:   group.add(pitch);
565: 
566:   const dirt = new THREE.Mesh(new THREE.RingGeometry(1, 1.1, 64), new THREE.MeshStandardMaterial({ color: '#6a5533', roughness: 1 }));
567:   dirt.rotation.x = -Math.PI / 2; dirt.scale.set(91, 56, 1);
568:   dirt.position.y = 0.01; group.add(dirt);
569: 
570:   // Field lines
571:   const lineMat = new THREE.LineBasicMaterial({ color: '#efe7cd', transparent: true, opacity: 0.7 });
572:   const ellipsePts = [];
573:   for (let i = 0; i <= 80; i++) {
574:     const a = (i / 80) * Math.PI * 2;
575:     ellipsePts.push(new THREE.Vector3(Math.cos(a) * 86, 0.04, Math.sin(a) * 52));
576:   }
577:   group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(ellipsePts), lineMat));
578:   const centerPts = [new THREE.Vector3(0, 0.04, -50), new THREE.Vector3(0, 0.04, 50)];
579:   group.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(centerPts), lineMat));
580:   const centerRing = new THREE.Mesh(new THREE.RingGeometry(14, 14.4, 48), new THREE.MeshBasicMaterial({ color: '#efe7cd', transparent: true, opacity: 0.45, side: THREE.DoubleSide }));
581:   centerRing.rotation.x = -Math.PI / 2; centerRing.position.y = 0.03; group.add(centerRing);
582: 
583:   // Stands
584:   const standMat = standard('#3c3b43', { roughness: 0.95, emissive: '#2b2a35', emissiveIntensity: 0.55 });
585:   const tiers = [
586:     { off: 10, y: 3, h: 6, d: 13 },
587:     { off: 22, y: 8.5, h: 6, d: 13 },
588:     { off: 34, y: 14, h: 6, d: 13 },
589:   ];
590:   const segs = 56;
591:   const standBlocks = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 1, 1), standMat, tiers.length * segs);
592:   const m = new THREE.Matrix4();
593:   const q = new THREE.Quaternion();
594:   const e = new THREE.Euler();
595:   let idx = 0;
596:   for (const t of tiers) {
597:     for (let i = 0; i < segs; i++) {
598:       const a = (i / segs) * Math.PI * 2;
599:       const rx = 95 + t.off, rz = 61 + t.off * 0.72;
600:       const x = Math.cos(a) * rx, z = Math.sin(a) * rz;
601:       e.set(0, -a + Math.PI / 2, 0);
602:       q.setFromEuler(e);
603:       const len = Math.max(9, (Math.PI * 2 * Math.sqrt((rx * rx + rz * rz) / 2) / segs) * 1.08);
604:       m.compose(new THREE.Vector3(x, t.y, z), q, new THREE.Vector3(len, t.h, t.d));
605:       standBlocks.setMatrixAt(idx++, m);
606:     }
607:   }
608:   standBlocks.receiveShadow = true;
609:   group.add(standBlocks);
610: 
611:   // Crowd
612:   const rand = mulberry32(seed);
613:   const crowdGeo = new THREE.BoxGeometry(0.6, 1.1, 0.6);
614:   const crowdMat = new THREE.MeshStandardMaterial({ roughness: 0.9 });
615:   const crowdMesh = new THREE.InstancedMesh(crowdGeo, crowdMat, crowd);
616:   const palette = [colors[0], colors[1], accent, '#e8e2d2', '#5b6c8c', '#a24a5c', '#4b7a5f'];
617:   const tmpColor = new THREE.Color();
618:   for (let i = 0; i < crowd; i++) {
619:     const tier = Math.floor(rand() * tiers.length);
620:     const t = tiers[tier];
621:     const a = rand() * Math.PI * 2;
622:     const rx = 95 + t.off, rz = 61 + t.off * 0.72;
623:     const jitter = (rand() - 0.5) * 10;
624:     const x = Math.cos(a) * (rx + jitter), z = Math.sin(a) * (rz + jitter * 0.7);
625:     const s = 0.75 + rand() * 0.55;
626:     m.compose(new THREE.Vector3(x, t.y + t.h / 2 + 0.9 + rand() * 0.8, z), q.identity(), new THREE.Vector3(s, s, s));
627:     crowdMesh.setMatrixAt(i, m);
628:     tmpColor.set(palette[Math.floor(rand() * palette.length)]);
629:     crowdMesh.setColorAt(i, tmpColor);
630:   }
631:   group.add(crowdMesh);
632: 
633:   // Outer wall
634:   const wallGeo = new THREE.CylinderGeometry(1, 1, 1, 64, 1, true);
635:   const wall = new THREE.Mesh(wallGeo, new THREE.MeshStandardMaterial({ color: '#2e2d33', emissive: '#23222c', emissiveIntensity: 0.5, roughness: 1, side: THREE.DoubleSide }));
636:   // Keep the perimeter barrier low: a full-height ring blocks the low-flight
637:   // camera's view across the pitch and hides the stands and goal hoops.
638:   wall.scale.set(118, 5, 79);
639:   wall.position.y = 2.5;
640:   group.add(wall);
641: 
642:   // Floodlight towers
643:   const poleMat = standard('#5a5b63', { metalness: 0.5, roughness: 0.6 });
644:   const lightMat = new THREE.MeshStandardMaterial({ color: '#fff2bd', emissive: '#ffe38a', emissiveIntensity: 3.2 });
645:   const corners = [[-116, -76], [116, -76], [-116, 76], [116, 76]];
646:   for (const [x, z] of corners) {
647:     const pole = new THREE.Mesh(new THREE.CylinderGeometry(1, 1.6, 56, 6), poleMat);
648:     pole.position.set(x, 28, z); group.add(pole);
649:     const panel = new THREE.Mesh(new THREE.BoxGeometry(14, 5, 1.5), lightMat);
650:     panel.position.set(x, 57, z); panel.lookAt(0, 30, 0); group.add(panel);
651:     const glow = glowSprite('#ffe9b0', 34, 0.45);
652:     glow.position.set(x, 57, z); group.add(glow);
653:   }
654: 
655:   // Banners
656:   for (let i = 0; i < 10; i++) {
657:     const a = (i / 10) * Math.PI * 2;
658:     const rx = 94, rz = 60;
659:     const x = Math.cos(a) * rx, z = Math.sin(a) * rz;
660:     const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.28, 23, 5), poleMat);
661:     pole.position.set(x, 11.5, z); group.add(pole);
662:     const flag = new THREE.Mesh(new THREE.PlaneGeometry(7, 11), new THREE.MeshStandardMaterial({
663:       color: i % 2 ? colors[0] : colors[1], side: THREE.DoubleSide, roughness: 0.9,
664:       emissive: accent, emissiveIntensity: 0.08,
665:     }));
666:     flag.position.set(x, 17, z);
667:     flag.lookAt(0, 17, 0);
668:     flag.rotateY(Math.PI / 2);
669:     group.add(flag);
670:     const crest = new THREE.Mesh(new THREE.CircleGeometry(1.6, 16), new THREE.MeshBasicMaterial({ color: accent, transparent: true, opacity: 0.95, side: THREE.DoubleSide }));
671:     crest.position.set(x, 17, z);
672:     crest.lookAt(0, 17, 0);
673:     crest.translateZ(0.08);
674:     group.add(crest);
675:   }
676: 
677:   // Hoops
678:   const hoopMat = new THREE.MeshStandardMaterial({
679:     color: '#d8ad4f', emissive: '#b47c1e', emissiveIntensity: 0.8, metalness: 0.7, roughness: 0.32,
680:   });
681:   const hoopData = [];
682:   if (hoops) {
683:     for (const side of [-1, 1]) {
684:       const baseX = side * 88;
685:       [8.5, 13.5, 18.5].forEach((y, i) => {
686:         const z = (i - 1) * 8;
687:         const poleX = baseX + side * 4.6;
688:         const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.34, 0.5, y + 4, 6), hoopMat);
689:         pole.position.set(poleX, (y + 4) / 2, z);
690:         group.add(pole);
691:         const arm = new THREE.Mesh(new THREE.BoxGeometry(4.8, 0.34, 0.34), hoopMat);
692:         arm.position.set(baseX + side * 2.3, y + 0.1, z);
693:         group.add(arm);
694:         const ring = new THREE.Mesh(new THREE.TorusGeometry(3.4 - i * 0.25, 0.26, 8, 26), hoopMat);
695:         ring.position.set(baseX, y, z);
696:         ring.rotation.y = Math.PI / 2;
697:         ring.castShadow = false;
698:         group.add(ring);
699:         const glow = glowSprite('#ffd97a', 7, 0.3);
700:         glow.position.set(baseX, y, z);
701:         group.add(glow);
702:         hoopData.push({ side, y, x: baseX, z, ring });
703:       });
704:     }
705:   }
706:   // big central crest on the field? scoreboard towers
707:   const boardMat = new THREE.MeshStandardMaterial({ color: '#161b2b', emissive: '#0c1220', roughness: 0.5 });
708:   const board = new THREE.Mesh(new THREE.BoxGeometry(34, 14, 2), boardMat);
709:   board.position.set(0, 25, -86);
710:   group.add(board);
711:   const boardGlow = new THREE.Mesh(new THREE.PlaneGeometry(30, 10), new THREE.MeshBasicMaterial({ color: accent, transparent: true, opacity: 0.22 }));
712:   boardGlow.position.set(0, 25, -84.9);
713:   group.add(boardGlow);
714: 
715:   scene.add(group);
716:   return { group, pitch, hoopData, crowdMesh, colors, accent };
717: }
