const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const target = targets.find(t => t.type === 'page' && t.url.startsWith('http://127.0.0.1:3002/'));
if (!target) throw new Error('Game page not found');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
ws.onmessage = event => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) { const { resolve } = pending.get(msg.id); pending.delete(msg.id); resolve(msg); }
  else if (msg.method === 'Runtime.consoleAPICalled') {
    const args = msg.params.args || [];
    if (args.some(arg => String(arg.value || arg.description || '').includes('APP_COLOR_TRACE'))) console.log('TRACE', JSON.stringify(args.map(a => a.value || a.description)));
  }
};
function send(method, params = {}) {
  const requestId = ++id;
  ws.send(JSON.stringify({ id: requestId, method, params }));
  return new Promise((resolve, reject) => {
    const timer = setTimeout(() => { pending.delete(requestId); reject(new Error(`${method} timeout`)); }, 15000);
    pending.set(requestId, { resolve: msg => { clearTimeout(timer); resolve(msg); } });
  });
}
await send('Runtime.enable');
const hook = await send('Runtime.evaluate', {expression:`(() => { const original = console.warn.bind(console); console.warn = (...args) => { if (String(args[0]).includes('Unknown color')) original('APP_COLOR_TRACE', args[0], new Error().stack); original(...args); }; return 'warn-hooked'; })()`, returnByValue:true});
console.log('HOOK', JSON.stringify(hook.result?.result?.value));
const run = await send('Runtime.evaluate', {expression:`(() => { game.createPlayer(); game.go('quid'); game.startCampaign(); game.startMatch(); return {mode:game.mode, active:!!game.active, role:game.active?.role}; })()`, returnByValue:true, awaitPromise:true});
console.log('START', JSON.stringify(run.result?.result?.value || run.result?.exceptionDetails));
await new Promise(resolve => setTimeout(resolve, 6000));
const state = await send('Runtime.evaluate', {expression:`({phase:game.active?.phase, elapsed:game.active?.elapsed, elements:[...document.querySelectorAll('.scoreboard,.quid-commentary,.quid-objective,.quid-minimap-wrap,.role-chip,.joystick-wrap,.quid-actions,.quid-boost,#quid-hud,.quid-banner')].map(e=>({class:e.className,id:e.id,rect:e.getBoundingClientRect().toJSON(),text:e.innerText})),warnings:performance.getEntriesByType('resource').filter(e=>e.name.includes('three.js')).map(e=>e.name)})()`, returnByValue:true});
console.log('STATE', JSON.stringify(state.result?.result?.value, null, 2));
ws.close();

