const targets = await (await fetch('http://127.0.0.1:9222/json/list')).json();
const target = targets.find(t => t.type === 'page' && t.url.startsWith('http://127.0.0.1:3002/'));
if (!target) throw new Error('Game page not found');
const ws = new WebSocket(target.webSocketDebuggerUrl);
await new Promise((resolve, reject) => { ws.onopen = resolve; ws.onerror = reject; });
let id = 0;
const pending = new Map();
ws.onmessage = event => {
  const msg = JSON.parse(event.data);
  if (msg.id && pending.has(msg.id)) { const { resolve } = pending.get(msg.id); pending.delete(msg.id); resolve(msg); }
  else if (msg.method === 'Runtime.consoleAPICalled') {
    const args = msg.params.args || [];
    if (args.some(arg => String(arg.value || arg.description || '').includes('Unknown color'))) console.log('COLOR_WARNING', args.map(a => a.value || a.description).join(' '));
  }
};
function send(method, params = {}) {
  const requestId = ++id; ws.send(JSON.stringify({ id: requestId, method, params }));
  return new Promise((resolve, reject) => { const timer = setTimeout(() => { pending.delete(requestId); reject(new Error(`${method} timeout`)); }, 15000); pending.set(requestId, { resolve: msg => { clearTimeout(timer); resolve(msg); } }); });
}
await send('Runtime.enable'); await send('Page.enable');
const start = await send('Runtime.evaluate', {expression:`(() => { game.createPlayer(); game.go('quid'); game.startCampaign(); game.startMatch(); return {mode:game.mode, active:!!game.active, role:game.active?.role}; })()`, returnByValue:true});
console.log('START', JSON.stringify(start.result?.result?.value || start.result?.exceptionDetails));
await new Promise(resolve => setTimeout(resolve, 9000));
const result = await send('Runtime.evaluate', {expression:`(() => { try { return {mode:game.mode,phase:game.active?.phase,viewport:[innerWidth,innerHeight],elements:[...document.querySelectorAll('.scoreboard,.quid-commentary,.quid-objective,.quid-minimap-wrap,.role-chip,.joystick-wrap,.quid-actions,.quid-boost,#quid-hud,.quid-banner')].map(e=>({class:e.className,id:e.id,rect:e.getBoundingClientRect().toJSON(),text:e.innerText})),camera:game.active ? {position:game.active.camera.position.toArray(),player:game.active.player.pos.toArray(),fov:game.active.camera.fov} : null,errors:window.__errors} } catch(e) { return {evalError:String(e),stack:e.stack}; } })()`, returnByValue:true});
console.log('STATE', JSON.stringify(result.result?.result?.value || result.result?.exceptionDetails, null, 2));
const shot = await send('Page.captureScreenshot', {format:'png', captureBeyondViewport:false});
const fs = await import('node:fs/promises');
await fs.writeFile('/tmp/opencode/mobile-gameplay-active-later.png', Buffer.from(shot.result.data, 'base64'));
ws.close();

